.screen-loader.is-visible .screen-loader-panel {
  transform: translateY(0) scale(1);
  opacity: 1;
}

.screen-loader-mark {
  display: block;
  width: 4.5rem;
  height: 4.5rem;
}

.screen-loader-mark img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.screen-loader-dots {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  height: 0.5rem;
}

.screen-loader-dots span {
  display: block;
  width: 0.4rem;
  height: 0.4rem;
  border-radius: 50%;
  background: var(--accent);
  opacity: 0.28;
  animation: screen-loader-dot 1.1s ease-in-out infinite;
}

.screen-loader-dots span:nth-child(2) {
  animation-delay: 0.16s;
}

.screen-loader-dots span:nth-child(3) {
  animation-delay: 0.32s;
}

@keyframes screen-loader-dot {
  0%, 70%, 100% {
    opacity: 0.28;
    transform: translateY(0);
  }
  35% {
    opacity: 1;
    transform: translateY(-0.15rem);
  }
}

@media (prefers-reduced-motion: reduce) {
  .screen-loader-dots span {
    animation: none !important;
    opacity: 0.7;
    transform: none;
  }
}

.screen-loader-label {
  margin: 4px 0 0;
  text-align: center;
  font-size: 0.92rem;
  font-weight: 500;
  color: var(--muted);
  letter-spacing: 0.01em;
  max-width: 22ch;
}

