(() => {
  const root = document.getElementById('screenLoader');
  const label = document.getElementById('screenLoaderLabel');
  if (label) label.textContent = 'Loading board…';
  root.hidden = false;
  root.classList.add('is-visible');
  root.classList.remove('is-done');
  root.setAttribute('aria-hidden', 'false');
  document.body.classList.add('screen-loading');
  return {
    hasRing: Boolean(document.getElementById('screenLoaderRing')),
    hasPct: Boolean(document.getElementById('screenLoaderPct')),
    mark: root.querySelector('.screen-loader-mark img')?.getAttribute('src') || null,
    dots: root.querySelectorAll('.screen-loader-dots span').length,
    label: label?.textContent || null,
    html: root.innerHTML.slice(0, 500),
  };
})()

